CREATE OR REPLACE FUNCTION public.write_audited_site_setting(p_actor uuid,p_email text,p_wallet text,p_key text,p_value jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE old jsonb; BEGIN IF NOT EXISTS(SELECT 1 FROM public.app_admins a JOIN public.profiles p ON p.id=p_actor WHERE a.email=lower(p_email) AND a.role='super_admin' AND NOT a.disabled AND lower(p.wallet_address)=lower(p_wallet)) THEN RAISE EXCEPTION 'Forbidden'; END IF; PERFORM pg_advisory_xact_lock(hashtext('site-setting:'||p_key)); SELECT value INTO old FROM public.app_settings WHERE key=p_key; IF p_key IN ('fees','rewards') AND old IS DISTINCT FROM p_value THEN RAISE EXCEPTION 'Financial settings require separately approved policy workflow'; END IF; INSERT INTO public.app_settings(key,value,updated_by,updated_at) VALUES(p_key,p_value,p_actor,now()) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_by=excluded.updated_by,updated_at=excluded.updated_at; INSERT INTO public.admin_audit_events(actor_user_id,actor_email,actor_role,object_type,object_id,action,old_value,new_value,reason) VALUES(p_actor,lower(p_email),'super_admin','site_setting',p_key,'UPDATED',old,p_value,'Authorized site settings update'); END $$;
REVOKE ALL ON FUNCTION public.write_audited_site_setting(uuid,text,text,text,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.write_audited_site_setting(uuid,text,text,text,jsonb) TO service_role;